def check_condition(n):
    """Checks if 3n^2 + n is divisible by 4."""
    return (3 * n**2 + n) % 4 == 0

# Range is [99, 206]
results = []
for n in range(99, 207):
    if check_condition(n):
        results.append(n)

print("Integers n in [99, 206] satisfying 3n^2 + n divisible by 4:")
print(results)

